package run.ikaros.finance; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/v2/finance/ledgers/{ledgerId}") public class FinanceClassificationController{private final FinanceClassificationService service;public FinanceClassificationController(FinanceClassificationService s){service=s;}@PostMapping("/categories")public Mono<CategoryView> category(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId,@Valid@RequestBody CreateCategoryRequest r){return service.createCategory(a,ledgerId,r);}@GetMapping("/categories")public Flux<CategoryView> categories(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId){return service.categories(a,ledgerId);}@PostMapping("/tags")public Mono<TagView> tag(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId,@Valid@RequestBody CreateTagRequest r){return service.createTag(a,ledgerId,r);}@GetMapping("/tags")public Flux<TagView> tags(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId){return service.tags(a,ledgerId);}}
